-- Real VTEX Mexican Basic Basket Catalog Seed for PostgreSQL
-- Generated: 2026-10-21 14:36:26
-- Summary: 7 categories, 51 providers, 134 products, 331 media records.

BEGIN;

-- 1. Categories
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

-- 2. Providers
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, address = EXCLUDED.address, logo_url = EXCLUDED.logo_url;

-- 3. Products
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, price_list_cents = EXCLUDED.price_list_cents, provider_id = EXCLUDED.provider_id, category_id = EXCLUDED.category_id;

-- 4. Media
ON CONFLICT (id) DO UPDATE SET url = EXCLUDED.url, is_main = EXCLUDED.is_main;

COMMIT;
