INSERT INTO products (id, name, description, price_list_cents, provider_id, category_id) VALUES
    ('prod-vtex-3108088', 'Tortilla de Maíz Amarillo Kg', 'Tortilla de Maíz Amarillo Kg - Tortilla de maíz nixtamalizada básica mexicana - Tortilla de maíz amarillo', 1250, 'prov-tortilleria', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3619926', 'Tortilla de Maíz 500g', 'Tortilla de Maíz 500g - Tortilla de maíz nixtamalizada básica mexicana - Tortillas frescas de harina de maíz', 1300, 'prov-tortilleria', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3107563', 'Tortilla Taquera de Maíz Amarillo Kg', 'Tortilla Taquera de Maíz Amarillo Kg - Tortilla de maíz nixtamalizada básica mexicana - Tortillla Taquera llamada así por su tamaño, perfecta para elaborar tacos.', 2700, 'prov-tortilleria', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3108086', 'Tortilla Taquera de Maíz Blanco Kg', 'Tortilla Taquera de Maíz Blanco Kg - Tortilla de maíz nixtamalizada básica mexicana - Tortillla Taquera llamada así por su tamaño, perfecta para elaborar tacos.', 2700, 'prov-tortilleria', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3247867', 'Tiritas de Tortilla de Maíz Selecto Brand Natural 500g', 'Tiritas de Tortilla de Maíz Selecto Brand Natural 500g - Tortilla de maíz nixtamalizada básica mexicana - Producto elaborado a base de harina de maíz *', 5100, 'prov-selecto-brand', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3108081', 'Tortillas Blanca Kg', 'Tortillas Blanca Kg - Tortilla de maíz nixtamalizada básica mexicana - Tortilla de maíz blanco', 1250, 'prov-tortilleria', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3250655', 'Arroz Super Extra Chedraui 900g', 'Arroz Super Extra Chedraui 900g - Arroz en grano super extra - Este cereal es el alimento básico más importante para una gran parte de la población de todo el mundo, principalmente por el alto valor energético que aporta.', 1400, 'prov-chedraui', 'cat-abarrotes'),
    ('prod-vtex-3008380', 'Arroz Verde Valle Super Extra 900g', 'Arroz Verde Valle Super Extra 900g - Arroz en grano super extra - Arroz súper extra Verde Valle, es un arroz de la variedad grano largo y siendo ideal para todo tipo de platillos, es el más común en México y su calidad es “SUPER EXTRA” ya que contiene más del 95% de granos enteros.', 3700, 'prov-verde-valle', 'cat-abarrotes'),
    ('prod-vtex-3696184', 'Arroz Italriso Súper Extra 800g', 'Arroz Italriso Súper Extra 800g - Arroz en grano super extra - Arroz Italriso Súper extra, es un arroz con el porcentaje mínimo de quebrado, asegurando granos enteros antes y durante la cocción.', 1990, 'prov-italriso', 'cat-abarrotes'),
    ('prod-vtex-3801889', 'Arroz Schettino Extra 900g', 'Arroz Schettino Extra 900g - Arroz en grano super extra', 2300, 'prov-schettino', 'cat-abarrotes'),
    ('prod-vtex-3247692', 'Arroz La Merced Super Extra 900g', 'Arroz La Merced Super Extra 900g - Arroz en grano super extra - Arroz La Merced, el poderoso grano rico en nutrientes.', 2000, 'prov-la-merced', 'cat-abarrotes'),
    ('prod-vtex-3321972', 'Arroz Super Extra Calidad Bueno Premium 900g', 'Arroz Super Extra Calidad Bueno Premium 900g - Arroz en grano super extra - Arroz Bueno Premium lleva a tu mesa el mejor arroz súper extra, grano entero que no se pega ni se bate al cocinar y puedas preparar tus platillos con el mejor arroz que es de Calidad Bueno.', 2800, 'prov-calidad-bueno', 'cat-abarrotes'),
    ('prod-vtex-3250691', 'Frijol Negro Chedraui 900g', 'Frijol Negro Chedraui 900g - Frijol negro mexicano seleccionado - Prepara unas ricas enfrijoladas y que mejor que con frijoles negros Chedraui, los cuales son altos en hierro y proteína vegetal.', 1890, 'prov-chedraui', 'cat-abarrotes'),
    ('prod-vtex-3431689', 'Frijoles La Sierra Negros Refritos 400g', 'Frijoles La Sierra Negros Refritos 400g - Frijol negro mexicano seleccionado - Los frijoles refritos son un platillo tradicional mexicano que se consume a cualquier hora y es la guarnición perfecta para cualquier platillo, por lo que no puede faltar en tu mesa, descubre todo el sabor que La Sierra trae a tu cocina con los deliciosos Frijoles Negros Refritos.', 1200, 'prov-la-sierra', 'cat-abarrotes'),
    ('prod-vtex-3358055', 'Frijoles Refritos Isadora Negros 400g', 'Frijoles Refritos Isadora Negros 400g - Frijol negro mexicano seleccionado - Frijoles Refritos Negros son la deliciosa receta con ingredientes naturales y sin conservadores de nuestros Frijoles Isadora. Listos en sólo 1 minuto y dos sencillos pasos, ideales para poder complementar tus platillos diarios.', 1500, 'prov-isadora', 'cat-abarrotes'),
    ('prod-vtex-3775953', 'Frijol Negro Michigan por Kg', 'Frijol Negro Michigan por Kg - Frijol negro mexicano seleccionado - Frijol Negro Michigan por kilo. *', 3850, 'prov-frutas-y-verduras', 'cat-abarrotes'),
    ('prod-vtex-3043738', 'Frijoles Negros La Costeña enteros 560g', 'Frijoles Negros La Costeña enteros 560g - Frijol negro mexicano seleccionado - El sabor por tradición en las mesas mexicanas es de los Frijoles negros enteros de La Costeña por su delicioso sabor, elaborado con frijoles negros, cebolla, chile jalapeño y sal es el compañero ideal para disfrutar en familia.', 1600, 'prov-la-costena', 'cat-abarrotes'),
    ('prod-vtex-3008238', 'Frijol Verde Valle Negro Querétaro 900g', 'Frijol Verde Valle Negro Querétaro 900g - Frijol negro mexicano seleccionado - Frijol Negro Querétaro, regularmente viene de Zacatecas y Durango, es un de tamaño mediano y de color negro brillante, cocido tiene una textura cremosa y su caldo es café oscuro, se consume principalmente en la Cd. de México, el sureste y el golfo de México.', 3850, 'prov-verde-valle', 'cat-abarrotes'),
    ('prod-vtex-3105808', 'Pan Blanco de Caja Selecto 675g', 'Pan Blanco de Caja Selecto 675g - Pan blanco de caja clásico - Pan de caja blanco de la marca Selecto, elaborado con harina blanca. *', 1800, 'prov-selecto-brand', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3106177', 'Pan de 7 Granos Selecto Fresh', 'Pan de 7 Granos Selecto Fresh - Pan blanco de caja clásico - Pan de caja elaborado con harina de 7 granos y semilla de linaza. *', 6200, 'prov-panaderia', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3716151', 'Pan de Caja Brioche 580g', 'Pan de Caja Brioche 580g - Pan blanco de caja clásico - Pan de Caja Brioche. *', 5990, 'prov-panaderia', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3106179', 'Pan con Semilla de Girasol Selecto Fresh', 'Pan con Semilla de Girasol Selecto Fresh - Pan blanco de caja clásico - Pan de caja elaborado con harina de semilla de girasol y semilla de girasol natural. *', 6200, 'prov-panaderia', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3106178', 'Pan de Centeno Natural Selecto Fresh', 'Pan de Centeno Natural Selecto Fresh - Pan blanco de caja clásico - Pan de caja elaborado con harina de centeno negro y avena. *', 6200, 'prov-panaderia', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3889258', 'Pan Bimbo Crossantines Hershey 60g', 'Pan Bimbo Crossantines Hershey 60g - Pan blanco de caja clásico - Listo para disfrutar. Disfrútalo directo del empaque o caliéntalo unos segundos para realzar el sabor y la textura del hojaldre. Ideal como snack, desayuno, postre o acompañamiento de café.', 2350, 'prov-bimbo', 'cat-panaderia-tortilleria'),
    ('prod-vtex-3880416', 'Aceite Nutrioli 850ml + Pasta para Sopa Fusilli Ve 200g', 'Aceite Nutrioli 850ml + Pasta para Sopa Fusilli Ve 200g - Pasta para sopa de trigo - Aceite vegetal acompañado de pasta fusilli, ideal para preparar comidas.', 2990, 'prov-nutrioli', 'cat-abarrotes'),
    ('prod-vtex-3090697', 'Pasta para Sopa La Moderna Fideo 2 220g', 'Pasta para Sopa La Moderna Fideo 2 220g - Pasta para sopa de trigo - Bolsa con 220g de pasta elaborada con sémola de trigo durum, enriquecida con vitaminas y hierro.', 1060, 'prov-la-moderna', 'cat-abarrotes'),
    ('prod-vtex-3090695', 'Pasta para Sopa La Moderna Fideo 0 220g', 'Pasta para Sopa La Moderna Fideo 0 220g - Pasta para sopa de trigo - Bolsa con 220g de pasta elaborada con sémola de trigo durum, enriquecida con vitaminas y hierro', 1200, 'prov-la-moderna', 'cat-abarrotes'),
    ('prod-vtex-3784151', 'Pasta Barilla Fusilli 450 g', 'Pasta Barilla Fusilli 450 g - Pasta para sopa de trigo - ¡Prueba el sabor de una pasta al dente, siempre perfecta! En Barilla nos apasiona la pasta y compartimos nuestra pasión con el mundo desde 1877, desde entonces, elaboramos la mejor pasta de Italia, diseñando diferentes tipos de cortes para combinar con cualquier salsa y siempre brindarte una experiencia de sabor.', 2500, 'prov-barilla', 'cat-abarrotes'),
    ('prod-vtex-3090704', 'Pasta para Sopa La Moderna Munición 220g', 'Pasta para Sopa La Moderna Munición 220g - Pasta para sopa de trigo - Bolsa con 220g de pasta elaborada con sémola de trigo durum, enriquecida con vitaminas y hierro', 1200, 'prov-la-moderna', 'cat-abarrotes'),
    ('prod-vtex-3090703', 'Pasta para Sopa La Moderna Moñito 220g', 'Pasta para Sopa La Moderna Moñito 220g - Pasta para sopa de trigo - Bolsa con 220g de pasta elaborada con sémola de trigo durum, enriquecida con vitaminas y hierro', 1200, 'prov-la-moderna', 'cat-abarrotes'),
    ('prod-vtex-3009948', 'Aceite 123 Vegetal 123 1L', 'Aceite 123 Vegetal 123 1L - Aceite vegetal comestible puro - Aceite 123 Vegetal te ayuda a preparar tus alimentos de una manera más sana ya que por su origen vegetal no contiene colesterol, ademas intensifica el sabor de los ingredientes que uses al cocinar.', 4200, 'prov-123', 'cat-abarrotes'),
    ('prod-vtex-3132396', 'Aceite Vegetal Nutrioli Puro de Soya 850ml', 'Aceite Vegetal Nutrioli Puro de Soya 850ml - Aceite vegetal comestible puro - Nutrioli es un aceite para cocinar 100% puro de soya que cuida tu salud, ya que cuenta con Omegas 3, 6 y 9, que ayudan a elevar tus niveles de colesterol bueno y reducir el malo, por su origen vegetal no contiene colesterol, es claro y su consistencia es muy ligera, además, contiene vitamina E un antioxidante natural.', 4290, 'prov-nutrioli', 'cat-abarrotes'),
    ('prod-vtex-3696190', 'Aceite Vegetal Comestible Ave 850ml', 'Aceite Vegetal Comestible Ave 850ml - Aceite vegetal comestible puro - Ave es un aceite vegetal de formulación mixta procesado bajo modernas técnicas de fabricación. Excelente para todas la necesidades de la cocina tales como cocer, freír, hornear y la preparación de aderezos para ensaladas, un aceite versátil y económico.', 2800, 'prov-ave', 'cat-abarrotes'),
    ('prod-vtex-3880415', 'Aceite Nutrioli 850ml + Pasta para Sopa Codo 200g', 'Aceite Nutrioli 850ml + Pasta para Sopa Codo 200g - Aceite vegetal comestible puro - Paquete con aceite vegetal y pasta tipo codo, práctico para tu cocina.', 2990, 'prov-nutrioli', 'cat-abarrotes'),
    ('prod-vtex-3691244', 'Aceite Vegetal Comestible Sabrosano Mantequilla 850ml', 'Aceite Vegetal Comestible Sabrosano Mantequilla 850ml - Aceite vegetal comestible puro - Sabrosano Mantequilla es un aceite vegetal resultado de una cuidadosa mezcla de soya y canola, para cocinar rico y saludable. Tiene un sutil aroma para que huela rico desde que lo pones en el sartén y que todo lo que prepares quede más sabroso', 4150, 'prov-sabro-sano', 'cat-abarrotes'),
    ('prod-vtex-3435745', 'Aceite Puro 100% de Canola 840ml', 'Aceite Puro 100% de Canola 840ml - Aceite vegetal comestible puro - Con Capullo disfruta el sabor íntegro de tus alimentos, pues resiste altas temperaturas, por eso no cambia el delicioso sabor de los alimentos. Tú te encargas del sazón y Capullo de conservar el sabor.', 5960, 'prov-capullo', 'cat-abarrotes'),
    ('prod-vtex-3793491', 'Azúcar Chedraui Estándar 1.8Kg', 'Azúcar Chedraui Estándar 1.8Kg - Azúcar estándar de caña pura - Azúcar Chedraui estándar está elaborada con caña 100% natural. Es el ingrediente ideal para endulzar bebidas y alimentos.', 3150, 'prov-chedraui', 'cat-abarrotes'),
    ('prod-vtex-3793492', 'Azúcar Chedraui Estándar 900g', 'Azúcar Chedraui Estándar 900g - Azúcar estándar de caña pura', 2499, 'prov-chedraui', 'cat-abarrotes'),
    ('prod-vtex-3804748', 'Azúcar Chedraui Refinada 900g', 'Azúcar Chedraui Refinada 900g - Azúcar estándar de caña pura - Azúcar Chedraui Refinada', 4000, 'prov-chedraui', 'cat-abarrotes'),
    ('prod-vtex-3152854', 'Atún Dolores Aleta Amarilla en Agua 130g', 'Atún Dolores Aleta Amarilla en Agua 130g - Atún en hojuelas en conserva - Dolores se ha caracterizado por ser el sabor de toda la vida. Su práctica presentación de 130g en agua es ideal para preparar deliciosas ensaladas y muchos otros platillos que le encantan a toda la familia. Atún Dolores es 100% libre de soya', 2200, 'prov-dolores', 'cat-abarrotes'),
    ('prod-vtex-3010228', 'Atún El Dorado Nutre en Agua 130g', 'Atún El Dorado Nutre en Agua 130g - Atún en hojuelas en conserva - Prueba atún aleta amarilla El Dorado Nutre en Agua 140g, que además de ser una fuente natural de proteína y Omega 3, está enriquecido con minerales (Vitamina C, Vitamina E, Zinc, Vitamina A, Selenio y Vitamina D). Atún El Dorado, la calidad se prueba.', 1250, 'prov-el-dorado', 'cat-abarrotes'),
    ('prod-vtex-3010221', 'Atún Dolores Aleta Amarilla en Agua 295g', 'Atún Dolores Aleta Amarilla en Agua 295g - Atún en hojuelas en conserva - El tamaño ideal para preparar recetas deliciosas recetas, con esta lata de Atún Dolores en Agua que rinde más de 2 latas, cocinar rico con poco tiempo, no será un problema.', 4300, 'prov-dolores', 'cat-abarrotes'),
